    map['inactive'] = Variable<bool>(inactive);
    if (!nullToAbsent || sourceUpdatedAt != null) {
      map['source_updated_at'] = Variable<String>(sourceUpdatedAt);
    }
    map['cached_at'] = Variable<DateTime>(cachedAt);
    return map;
  }

